@router.post("/import/groww-csv")
async def import_groww_csv(file: UploadFile = File(...), background_tasks: BackgroundTasks = Depends()):
    if file.size > 10 * 1024 * 1024:
        raise HTTPException(status_code=status.HTTP_413_REQUEST_ENTITY_TOO_LARGE, detail="File size limit exceeded")
    if file.content_type != "text/csv":
        raise HTTPException(status_code=status.HTTP_415_UNSUPPORTED_MEDIA_TYPE, detail="Unsupported file type")
    rows = parse_groww_csv(file.file)
    for row in rows:
        upsert_holding(row, mode="add_lot")
    background_tasks.add_task(backfill_price_history, row["symbol"], row["asset_type"])
    return JSONResponse(content={"state": "ok"})

@router.post("/import/cas")
async def import_cas(file: UploadFile = File(...), background_tasks: BackgroundTasks = Depends()):
    if file.size > 10 * 1024 * 1024:
        raise HTTPException(status_code=status.HTTP_413_REQUEST_ENTITY_TOO_LARGE, detail="File size limit exceeded")
    if file.content_type != "application/pdf":
        raise HTTPException(status_code=status.HTTP_415_UNSUPPORTED_MEDIA_TYPE, detail="Unsupported file type")
    rows = parse_cas(file.file)
    for row in rows:
        upsert_holding(row, mode="set_snapshot")
    return JSONResponse(content={"state": "ok"})

